mapper.update:
update company
name = #{name}, type = #{type}, city = #{city}, logo = #{logo}, description = #{description}, status = #{status}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select * from company

    and name like concat('%', #{name}, '%')
    and type = #{type}
    and status = #{status}

order by create_time desc
